package ae;

import java.math.BigDecimal;
import java.time.YearMonth;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.TreeMap;
import java.util.stream.Collector;
import java.util.stream.Collectors;

/** Stream-based analytics over orders. All results are unmodifiable. */
public final class Analytics {
    private Analytics() {}

    /** Custom collector; the mutable accumulator is a one-element array holding an immutable Stats. */
    public static Collector<Order, ?, Stats> statsCollector() {
        return Collector.of(
                () -> new Stats[] {Stats.EMPTY},
                (acc, o) -> acc[0] = acc[0].accept(o.amount()),
                (a, b) -> {
                    a[0] = a[0].combine(b[0]);
                    return a;
                },
                acc -> acc[0]);
    }

    public static Map<String, Stats> statsByCustomer(List<Order> orders) {
        return Collections.unmodifiableMap(
                orders.stream().collect(Collectors.groupingBy(Order::customer, TreeMap::new, statsCollector())));
    }

    public static Optional<String> topCategory(List<Order> orders, String customer) {
        return orders.stream()
                .filter(o -> o.customer().equals(customer))
                .collect(Collectors.groupingBy(Order::category, TreeMap::new,
                        Collectors.reducing(BigDecimal.ZERO, Order::amount, BigDecimal::add)))
                .entrySet().stream()
                // TreeMap order + stable max-by-first: keep earlier key on equal totals
                .reduce((a, b) -> b.getValue().compareTo(a.getValue()) > 0 ? b : a)
                .map(Map.Entry::getKey);
    }

    public static Map<Boolean, List<Order>> splitAtThreshold(List<Order> orders, BigDecimal threshold) {
        Map<Boolean, List<Order>> m = orders.stream()
                .collect(Collectors.partitioningBy(o -> o.amount().compareTo(threshold) >= 0));
        return Map.of(true, List.copyOf(m.get(true)), false, List.copyOf(m.get(false)));
    }

    public static Map<YearMonth, BigDecimal> monthlyTotals(List<Order> orders) {
        return Collections.unmodifiableMap(orders.stream().collect(Collectors.groupingBy(
                o -> YearMonth.from(o.date()), TreeMap::new,
                Collectors.reducing(BigDecimal.ZERO, Order::amount, BigDecimal::add))));
    }
}

package ae;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Objects;

/** An immutable purchase. */
public record Order(String customer, String category, BigDecimal amount, LocalDate date) {
    public Order {
        Objects.requireNonNull(customer, "customer");
        Objects.requireNonNull(category, "category");
        Objects.requireNonNull(amount, "amount");
        Objects.requireNonNull(date, "date");
        if (amount.signum() < 0) {
            throw new IllegalArgumentException("amount must be >= 0");
        }
    }
}

package ae;

import java.util.List;
import java.util.function.Predicate;

/** Predicate combinators over a defensive copy of their inputs. */
public final class Rules {
    private Rules() {}

    public static <T> Predicate<T> allOf(List<Predicate<T>> ps) {
        List<Predicate<T>> copy = List.copyOf(ps);
        return t -> copy.stream().allMatch(p -> p.test(t));
    }

    public static <T> Predicate<T> anyOf(List<Predicate<T>> ps) {
        List<Predicate<T>> copy = List.copyOf(ps);
        return t -> copy.stream().anyMatch(p -> p.test(t));
    }

    public static <T> Predicate<T> noneOf(List<Predicate<T>> ps) {
        List<Predicate<T>> copy = List.copyOf(ps);
        return t -> copy.stream().noneMatch(p -> p.test(t));
    }
}

package ae;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Objects;
import java.util.Optional;

/** Immutable running statistics over amounts. min/max are null only when count is 0. */
public record Stats(long count, BigDecimal sum, BigDecimal min, BigDecimal max) {
    public static final Stats EMPTY = new Stats(0, BigDecimal.ZERO, null, null);

    /** Returns a new Stats including {@code v}. */
    public Stats accept(BigDecimal v) {
        Objects.requireNonNull(v, "v");
        if (count == 0) {
            return new Stats(1, v, v, v);
        }
        return new Stats(count + 1, sum.add(v), min.min(v), max.max(v));
    }

    /** Merges two Stats; associative, with EMPTY as identity. */
    public Stats combine(Stats o) {
        if (o.count == 0) {
            return this;
        }
        if (count == 0) {
            return o;
        }
        return new Stats(count + o.count, sum.add(o.sum), min.min(o.min), max.max(o.max));
    }

    /** Mean at scale 2, HALF_UP; empty when there is no data. */
    public Optional<BigDecimal> mean() {
        if (count == 0) {
            return Optional.empty();
        }
        return Optional.of(sum.divide(BigDecimal.valueOf(count), 2, RoundingMode.HALF_UP));
    }
}

